    const STOP: usize = 1usize << (usize::BITS - 1);

    let shared = Arc::new(Shared {
        a: Mutex::new(()),
        b: Mutex::new(()),
        sa: Semaphore::new(),
        sb: Semaphore::new(),
        flag: AtomicUsize::new(0),
    });

